#!/usr/bin/env python3
"""Regenerates woff2.inc: WOFF2 fonts made by fontTools' encoder
(pip install fonttools brotli), which Zepra's own decoder is tested against.

kWoff2Subset is DejaVu Sans cut down to a few glyphs, hinting kept, with the
glyf, loca and hmtx transforms on; one glyph is marked OVERLAP_SIMPLE so the
overlap bitmap is used. kWoff2Glyphs lists what each glyph must look like
after decoding, taken from the original font. kWoff2Collection is a two-font
collection sharing a table, built by hand since fontTools can't write one.

    python3 gen_woff2.py /usr/share/fonts/truetype/dejavu/DejaVuSans.ttf
"""
import io, os, struct, sys, zlib
import brotli
from fontTools import subset
from fontTools.ttLib import TTFont, woff2

def arr(name, b):
    lines = ["    " + ", ".join("0x%02x" % x for x in b[i:i + 16]) + "," for i in range(0, len(b), 16)]
    return "const uint8_t %s[] = {\n%s\n};\n" % (name, "\n".join(lines))

src = sys.argv[1] if len(sys.argv) > 1 else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
opts = subset.Options()
opts.hinting = True
opts.layout_features = []
opts.name_IDs = [1, 2]
opts.notdef_outline = True
font = TTFont(src)
sub = subset.Subsetter(opts)
sub.populate(text="Zepra éÅ0")
sub.subset(font)
for t in ("GPOS", "GSUB", "GDEF", "kern", "FFTM"):
    if t in font: del font[t]
font["glyf"]["e"].flags[0] |= 0x40  # OVERLAP_SIMPLE, to exercise the overlap bitmap
buf = io.BytesIO(); font.save(buf); ttf = buf.getvalue()
font = TTFont(io.BytesIO(ttf))
out = io.BytesIO()
woff2.compress(io.BytesIO(ttf), out, transform_tables={"glyf", "loca", "hmtx"})
w2 = out.getvalue()

# What every glyph must decode to: composites flattened, as FreeType sees them
glyf = font["glyf"]; hmtx = font["hmtx"]
rows = []
for gid, name in enumerate(font.getGlyphOrder()):
    g = glyf[name]
    coords, ends, flags = g.getCoordinates(glyf)
    packed = b"".join(struct.pack(">hhB", int(x), int(y), f & 1) for (x, y), f in zip(coords, flags))
    kind = "composite" if g.isComposite() else ("empty" if g.numberOfContours == 0 else "simple")
    rows.append('    {"%s", %d, %d, %d, %d, 0x%08xu},  // %s' %
                (name, len(ends), len(coords), hmtx[name][0], hmtx[name][1], zlib.crc32(packed), kind))
tables = []
for tag in sorted(font.reader.keys()):
    if tag in ("glyf", "loca", "hmtx", "head", "DSIG"): continue
    tables.append('    {"%s", 0x%08xu, %d},' % (tag, zlib.crc32(font.reader[tag]), len(font.reader[tag])))

# A collection: two fonts that share 'name' (null transforms only)
def tbl(tag, data): return (tag, data)
shared = tbl(b"name", b"shared name table" * 3)
fa = [tbl(b"cmap", b"\x00\x01cmap of A"), shared]
fb = [tbl(b"cmap", b"\x00\x02cmap of font B!"), tbl(b"OS/2", bytes(range(40))), shared]
dir_tables = [fa[0], shared, fb[0], fb[1]]
known = {b"cmap": 0, b"name": 5, b"OS/2": 6}
def b128(n):
    out = [n & 0x7F]; n >>= 7
    while n: out.append(0x80 | (n & 0x7F)); n >>= 7
    return bytes(reversed(out))
directory = b"".join(bytes([known[t]]) + b128(len(d)) for t, d in dir_tables)
coll = struct.pack(">I", 0x00010000) + bytes([2])
coll += bytes([2]) + struct.pack(">I", 0x00010000) + bytes([0, 1])
coll += bytes([3]) + struct.pack(">I", 0x00010000) + bytes([2, 3, 1])
comp = brotli.compress(b"".join(d for _, d in dir_tables))
total = 48 + len(directory) + len(coll) + len(comp)
hdr = struct.pack(">4sIIHHIIHHIIIII", b"wOF2", 0x74746366, total, len(dir_tables), 0, 0, len(comp), 1, 0, 0, 0, 0, 0, 0)
collection = hdr + directory + coll + comp

with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "woff2.inc"), "w") as f:
    f.write("// Generated by gen_woff2.py with fontTools' WOFF2 encoder and the reference\n"
            "// Brotli encoder, which Zepra's own decoder is tested against. Do not edit.\n")
    f.write(arr("kWoff2Subset", w2))
    f.write("\nstruct Woff2Glyph {\n    const char* name;\n    int contours, points, advance, lsb;\n    uint32_t crc;  // CRC-32 of (int16 x, int16 y, uint8 on-curve) per point, big-endian\n};\n")
    f.write("const Woff2Glyph kWoff2Glyphs[] = {\n" + "\n".join(rows) + "\n};\n")
    f.write("\nstruct Woff2TableCrc {\n    const char* tag;\n    uint32_t crc;\n    uint32_t length;\n};\n")
    f.write("// Tables stored without a transform must come out byte for byte\n")
    f.write("const Woff2TableCrc kWoff2Tables[] = {\n" + "\n".join(tables) + "\n};\n\n")
    f.write(arr("kWoff2Collection", collection))
print(len(ttf), "byte subset ->", len(w2), "byte WOFF2;", len(rows), "glyphs")
